+      .option input {
+        width: 1.1rem;
+        height: 1.1rem;
+        margin: 0;
+        accent-color: var(--accent);
+        flex: 0 0 auto;
+      }
+
+      .option-label {
+        font-size: 1rem;
+        line-height: 1.3;
+      }
+
+      .actions {
+        display: flex;
+        justify-content: flex-end;
+        margin-top: 1rem;
