        font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top, #18284a 0%, transparent 38%),
          linear-gradient(180deg, var(--bg) 0%, #09101d 100%);
        color: var(--text);
      }

      a {
        color: inherit;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: var(--accent);
        color: #08101f;
        font-weight: 700;
        text-decoration: none;
        transform: translateY(-200%);
        transition: transform 160ms ease;
        z-index: 1000;
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      main {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 5rem 1.25rem 2rem;
      }

      .shell {
        width: min(100%, 44rem);
      }

      .hero {
        margin-bottom: 1rem;
      }

      .eyebrow {
        margin: 0 0 0.5rem;
        color: var(--accent-strong);
        font-size: 0.875rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 4vw, 3.25rem);
        line-height: 1.05;
      }

      .description {
        margin: 0.75rem 0 0;
        max-width: 34rem;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.6;
      }

      .card {
        margin-top: 1.75rem;
        padding: clamp(1.25rem, 2.6vw, 2rem);
        border: 1px solid var(--border);
        border-radius: var(--radius);
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), rgba(255, 255, 255, 0.01)),
          var(--bg-elevated);
        box-shadow: var(--shadow);
      }

      .form-field {
        padding: 1.25rem;
        border: 1px solid var(--border);
        border-radius: calc(var(--radius) - 6px);
        background: var(--bg-panel);
      }

      fieldset {
        margin: 0;
        padding: 0;
        border: 0;
        min-width: 0;
      }

      legend {
        padding: 0;
        font-size: 1.1rem;
        font-weight: 700;
      }

      .required {
        color: var(--accent-strong);
      }

      .helper-text {
        margin: 0.5rem 0 0;
        color: var(--muted);
        line-height: 1.5;
      }

      .options {
        display: grid;
        gap: 0.75rem;
        margin-top: 1rem;
      }

      .option {
        display: flex;
        align-items: center;
        gap: 0.85rem;
        padding: 0.95rem 1rem;
        border: 1px solid var(--border);
        border-radius: 16px;
        background: rgba(255, 255, 255, 0.02);
        transition: border-color 160ms ease, background-color 160ms ease, transform 160ms ease;
      }

      .option:hover {
        border-color: var(--border-strong);
        background: rgba(122, 162, 255, 0.06);
      }

      .option input {
        width: 1.1rem;
        height: 1.1rem;
        margin: 0;
        accent-color: var(--accent);
        flex: 0 0 auto;
      }

      .option-label {
        font-size: 1rem;
        line-height: 1.3;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
        margin-top: 1rem;
      }

      button {
        appearance: none;
        border: 1px solid transparent;
        border-radius: 999px;
        padding: 0.9rem 1.35rem;
        background: linear-gradient(180deg, #8db0ff, #6e95f5);
        color: #06101f;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        box-shadow: 0 12px 30px rgba(110, 149, 245, 0.28);
      }

      button:hover {
        filter: brightness(1.04);
      }

      button:focus-visible,
      input:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      .status {
        min-height: 1.5rem;
        margin-top: 0.9rem;
        color: #ffd79a;
        font-weight: 600;
      }

      .option[aria-invalid="true"] {
        border-color: #d98c8c;
      }

      @media (max-width: 520px) {
        main {
          padding-inline: 1rem;
        }

        .actions {
          justify-content: stretch;
        }

        button {
          width: 100%;
        }
      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --bg-elevated: Canvas;
          --bg-panel: Canvas;
          --border: ButtonBorder;
          --border-strong: ButtonBorder;
          --text: CanvasText;
          --muted: CanvasText;
          --accent: LinkText;
          --accent-strong: LinkText;
          --focus: Highlight;
        }

        .skip-link,
        .card,
        .form-field,
        .option,
        button {
          forced-color-adjust: auto;
          background: Canvas;
          color: CanvasText;
          border-color: ButtonBorder;
          box-shadow: none;
        }

        button {
          background: ButtonFace;
          color: ButtonText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>

    <script>
      const h = (tag, attrs = {}, children = []) => {
        const el = document.createElement(tag);
        for (const [key, value] of Object.entries(attrs)) {
          if (key === "className") {
            el.className = value;
          } else if (key === "textContent") {
            el.textContent = value;
          } else if (key.startsWith("on") && typeof value === "function") {
            el.addEventListener(key.slice(2).toLowerCase(), value);
          } else if (value !== false && value != null) {
            el.setAttribute(key, value === true ? "" : value);
          }
        }
        for (const child of [].concat(children)) {
          if (child == null) continue;
          el.append(child.nodeType ? child : document.createTextNode(child));
        }
        return el;
      };

      function RadioOption({ id, name, value, label, checked, required }) {
        const input = h("input", {
          type: "radio",
          id,
          name,
          value,
          checked,
          required,
        });

        const labelEl = h("label", { className: "option", for: id }, [
          input,
          h("span", { className: "option-label", textContent: label }),
        ]);

        return labelEl;
      }

      function NotificationForm() {
        const status = h("p", {
          className: "status",
          id: "notification-status",
          "aria-live": "polite",
        });

        const firstRadioId = "notification-email";
        const options = [
          { id: firstRadioId, value: "email", label: "Email" },
          { id: "notification-sms", value: "sms", label: "SMS" },
          { id: "notification-push", value: "push", label: "Push Notifications" },
        ];

        const form = h("form", {
          novalidate: "",
          "aria-describedby": "notification-help notification-status",
          onsubmit: (event) => {
            event.preventDefault();
            const selected = form.querySelector('input[name="notification"]:checked');
            const radios = form.querySelectorAll('input[name="notification"]');

            radios.forEach((radio) => radio.removeAttribute("aria-invalid"));

            if (!selected) {
              radios.forEach((radio) => radio.setAttribute("aria-invalid", "true"));
              status.textContent = "Please choose one notification method before continuing.";
              const first = form.querySelector(`#${CSS.escape(firstRadioId)}`);
              first.focus();
              return;
            }

            status.textContent = `You selected ${selected.value === "push" ? "Push Notifications" : selected.value[0].toUpperCase() + selected.value.slice(1)}.`;
          },
        }, [
          h("div", { className: "form-field" }, [
            h("fieldset", {}, [
              h("legend", {}, [
                "How do you prefer to receive notifications?",
                h("span", { className: "required", textContent: " *" }),
              ]),
              h("p", {
                className: "helper-text",
                id: "notification-help",
                textContent: "Choose one option so we can tailor the alerts you receive.",
              }),
              h("div", { className: "options" }, [
                ...options.map((option, index) =>
                  RadioOption({
                    ...option,
                    name: "notification",
                    checked: false,
                    required: index === 0,
                  }),
                ),
              ]),
            ]),
          ]),
          h("div", { className: "actions" }, [
            h("button", { type: "submit" }, "Submit"),
          ]),
          status,
        ]);
        return form;
      }

      function App() {
        return h("main", { id: "main-content" }, [
          h("div", { className: "shell" }, [
            h("header", { className: "hero" }, [
              h("p", { className: "eyebrow", textContent: "Preferences" }),
              h("h1", { textContent: "Notification delivery" }),
              h("p", {
                className: "description",
                textContent: "Tell us how you want to hear from us, and we will keep your experience consistent across updates.",
              }),
            ]),
            h("section", { className: "card", "aria-label": "Notification preference form" }, [
              NotificationForm(),
            ]),
          ]),
        ]);
      }

      document.getElementById("app").append(App());
    </script>
  </body>
</html>
