         --bg: #0b1220;
         --bg-elevated: #111a2e;
         --bg-panel: #16213a;
         --border: #273553;
         --border-strong: #3c547f;
         --text: #e7edf7;
         --muted: #aab7cf;
         --accent: #7aa2ff;
         --accent-strong: #9bb8ff;
         --focus: #d8e4ff;
         --shadow: 0 24px 60px rgba(0, 0, 0, 0.38);
         --radius: 20px;
       }

       * {
         box-sizing: border-box;
       }

       html {
         scroll-behavior: smooth;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         background:
           radial-gradient(circle at top, #18284a 0%, transparent 38%),
           linear-gradient(180deg, var(--bg) 0%, #09101d 100%);
         color: var(--text);
       }

       a {
         color: inherit;
       }

       .skip-link {
         position: absolute;
         left: 1rem;
         top: 1rem;
         padding: 0.75rem 1rem;
         border-radius: 999px;
         background: var(--accent);
         color: #08101f;
         font-weight: 700;
         text-decoration: none;
         transform: translateY(-200%);
         transition: transform 160ms ease;
         z-index: 1000;
       }

       .skip-link:focus {
         transform: translateY(0);
         outline: 3px solid var(--focus);
         outline-offset: 3px;
       }

       main {
         min-height: 100vh;
         display: grid;
         place-items: center;
         padding: 5rem 1.25rem 2rem;
       }

       .shell {
         width: min(100%, 44rem);
       }

       .hero {
         margin-bottom: 1rem;
       }

       .eyebrow {
         margin: 0 0 0.5rem;
         color: var(--accent-strong);
         font-size: 0.875rem;
         letter-spacing: 0.12em;
         text-transform: uppercase;
       }

       h1 {
         margin: 0;
         font-size: clamp(2rem, 4vw, 3.25rem);
         line-height: 1.05;
       }

       .description {
         margin: 0.75rem 0 0;
         max-width: 34rem;
         color: var(--muted);
         font-size: 1.05rem;
         line-height: 1.6;
       }

       .card {
         margin-top: 1.75rem;
         padding: clamp(1.25rem, 2.6vw, 2rem);
         border: 1px solid var(--border);
         border-radius: var(--radius);
         background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), rgba(255, 255, 255, 0.01)),
           var(--bg-elevated);
         box-shadow: var(--shadow);
       }

       .form-field {
         padding: 1.25rem;
         border: 1px solid var(--border);
         border-radius: calc(var(--radius) - 6px);
         background: var(--bg-panel);
       }

